export function keywords(text: string): string[] {
  const han = [...text].filter((c) => HAN.test(c));
  const out = new Set<string>();
  for (let i = 0; i + 2 <= han.length; i++) {
    const w = han[i] + han[i + 1];
    if (!FILLER.test(w)) out.add(w);
  }
  return [...out];
}

